create policy "published activity readable" on public.activity_posts
  as permissive
  for select
  to public
  using (published_at IS NOT NULL AND (car_id IS NULL OR COALESCE(( SELECT c.is_public
   FROM public.cars c
  WHERE c.id = activity_posts.car_id), false)) OR (( SELECT auth.uid() AS uid)) = author_id);
